class Solution {
public:
    long long singleDivisorTriplet(vector<int>& nums) {
        long long f[101]={};
        for (int x:nums) ++f[x];
        long long ans=0;
        for (int a=1;a<=100;++a) if (f[a])
            for (int b=a;b<=100;++b) if (f[b])
                for (int c=b;c<=100;++c) if (f[c]) {
                    int s=a+b+c;
                    int count=(s%a==0)+(s%b==0)+(s%c==0);
                    if (count!=1) continue;
                    long long ways=0;
                    if (a==b && b==c) ways=f[a]*(f[a]-1)*(f[a]-2);
                    else if (a==b) ways=3*f[a]*(f[a]-1)*f[c];
                    else if (b==c) ways=3*f[a]*f[b]*(f[b]-1);
                    else ways=6*f[a]*f[b]*f[c];
                    ans+=ways;
                }
        return ans;
    }
};
